#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.44.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.44.0.json').read_text())
PREV=json.loads((ROOT/'history/release-manifest-v0.43.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.44.0.js').read_text()
REF=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-reference-library-v1.js').read_text()
COLL=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-collections-v1.js').read_text()
SEARCH=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-knowledge-search-v1.js').read_text()
IK=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-integrated-knowledge-v1.js').read_text()
NAV=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-navigation-v1.js').read_text()
PORT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-portability-v1.js').read_text()
REVIEW=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-review-provenance-v1.js').read_text()
def c(x,l):
 if not x: raise SystemExit('FAIL - '+l)
 print('PASS - '+l)
c('Version: 0.44.0' in MAIN,'plugin version')
c((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.44.0','0.43.0','Citation Library & Reference Management'),'manifest release lineage')
c((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'schema-stable storage 35 / project 20 / export 20')
c(not MAN['schema_migration_required'] and MAN['migration']['schema_stable'] and MAN['migration']['citation_library_only_release'] and not MAN['migration']['canonical_data_rewrite'],'schema-stable citation-library boundary')
c(PREV['migration']['collections_views_only_release'],'v0.43 Research Collections history retained')
c('/wp-json/sc-workspace/v1/citation-library-contract' in MAN['rest_routes'] and "'/citation-library-contract'" in PHP,'Citation Library REST contract')
c(MAN['reference_schema']=='sc-workspace-reference/1.0' and MAN['reference_library_schema']=='sc-workspace-reference-library/1.0' and MAN['citation_preferences_schema']=='sc-workspace-citation-preferences/1.0','Reference Library schemas')
cl=MAN['citation_library']
c(cl['storage']=='browser-local-workspace-library' and cl['max_references']==1500,'browser-local reusable reference library')
c(cl['duplicate_detection']==['normalized-doi','bibliographic-fingerprint'] and not cl['automatic_deduplication'],'deterministic duplicate review / no auto merge')
c(cl['citation_keys']=='deterministic-local-collision-safe' and cl['styles']==['apa7','chicago-author-date','mla9','ieee'],'citation keys and style previews')
c(cl['canonical_origin_refs'] and cl['portable_export_import'],'canonical-origin links and portable exchange')
c(not cl['metadata_lookup'] and not cl['metadata_inference'] and not cl['automatic_project_mutation'] and not cl['automatic_ai'],'no lookup / inference / project mutation / AI')
c(all(x in REF for x in ('function normalizeDoi','function normalizeReference','function fingerprint','function duplicateGroups','function uniqueCitationKey','function format(raw','function referenceFromEntry','function exportPackage')),'Reference Library runtime')
c(all(x in PHP for x in ('data-scw-reference-library','data-scw-citation-style','data-scw-reference-add-selected','data-scw-reference-list','data-scw-reference-detail')),'Reference Library presentation')
c(all(x in JS for x in ('loadReferenceLibrary','persistReferenceLibrary','renderReferenceLibrary','referenceFromEntry','exportPackage')),'Reference Library integration')
g=MAN['governance']
c(g['citation_library_browser_local'] and not g['citation_library_mutates_projects'] and g['citation_library_missing_fields_remain_missing'],'browser local / no project mutation / missing stays missing')
c(not g['citation_library_metadata_lookup'] and not g['citation_library_metadata_inference'] and not g['citation_library_automatic_merge'] and not g['citation_library_automatic_ai'],'no metadata inference / merge / AI')
c(g['citation_library_duplicate_reasons_visible'] and g['citation_library_canonical_origin_links_explicit'],'inspectable duplicate and origin provenance')
c('function smartCollection' in COLL and 'function dashboard(entries,state,searchApi,current={})' in COLL,'v0.43 Research Collections retained')
c('function search(entries,prefs={},state={})' in SEARCH and 'function related(target,entries,state)' in SEARCH,'v0.42 Advanced Retrieval retained')
c('function derive(state)' in IK and 'duplicatesCanonicalContent:false' in IK,'v0.40 Integrated Knowledge retained')
c('function areaForView(view)' in NAV and all(x in NAV for x in ("start:{label:'Start'","projects:{label:'Projects'","research:{label:'Research'","review:{label:'Review'","exchange:{label:'Exchange'")),'v0.41 unified navigation retained')
c('expectedRevision' in PORT and 'silentLastWriteWins:false' in PORT,'v0.38 conflict-safe notebook sync retained')
c(all(x in REVIEW for x in ('buildReview','buildReconciliation','shadowProvenanceDatabase:false')),'v0.39 Notebook Review & Provenance retained')
c((REG['public_version'],REG['previous_version'])==('0.44.0','0.43.0'),'registry lineage')
c("BACKUP_KEY = 'sc_workspace_registry_backup_v0440'" in REGPHP and 'LEGACY_PENDING_KEY_V0430' in REGPHP,'registry retry lineage')
c((ROOT/'history/release-manifest-v0.43.0.json').exists() and (ROOT/'history/workspace-product-record-v0.43.0.json').exists(),'v0.43 history preserved')
files=list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.44.0.json',ROOT/'registry/workspace-product-record-v0.44.0.json']
for p in files: json.loads(p.read_text())
print(f'PASS - {len(files)} JSON schema/release records')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.44.0 — Citation Library & Reference Management')
